// Le Cercle du Domaine : fil, décisions et activités de démonstration dans ce navigateur.
function circleInit(){state.circleV11??={decisions:[],activities:[],signups:[],saved:[]};state.forum??={threads:[],replies:[],votes:[],saved:[]}}
circleInit();save();let circleTab='fil',circleQuery='';
const circleDecisionSeeds=[{id:'seed-d1',title:'Comment organiser les repas partagés ?',text:'Choisir ensemble un rythme simple pour préparer et partager un repas à la maison commune.',options:['Chaque semaine','Deux fois par mois','Une fois par mois'],deadline:datePlus(nowDate(),7),stage:'vote',example:true},{id:'seed-d2',title:'Quel prochain atelier au jardin ?',text:'Une proposition à discuter avant de passer au vote. Les habitants peuvent préciser leurs envies dans le fil associé.',options:['Compost & sol vivant','Semis de saison','Gestion de l’eau'],deadline:datePlus(nowDate(),10),stage:'discussion',example:true}];
const circleActivitySeeds=[{id:'seed-a1',title:'Récolte & café au potager',desc:'Observer les cultures, récolter ensemble et partager un café. Apporter un panier et des chaussures adaptées.',date:datePlus(nowDate(),3),time:'09:00',place:'Potager commun',capacity:12,category:'Jardin',photo:'garden',example:true},{id:'seed-a2',title:'Le dîner des voisins',desc:'Chacun propose un plat à partager. Les ingrédients et allergènes seront à préciser entre participants.',date:datePlus(nowDate(),5),time:'19:00',place:'Maison commune',capacity:16,category:'Convivialité',photo:'house',example:true},{id:'seed-a3',title:'Balade à vélo du Domaine',desc:'Une sortie douce pour découvrir les alentours. Réserver un vélo dans la démo si nécessaire.',date:datePlus(nowDate(),7),time:'10:00',place:'Point mobilité',capacity:6,category:'Mobilité',photo:'bike',example:true}];
function circleDecisions(){circleInit();return [...state.circleV11.decisions,...circleDecisionSeeds.map(d=>({...d,...(state.circleV11.saved.find(s=>s.id===d.id)||{})}))]}
function circleActivities(){circleInit();return [...state.circleV11.activities,...circleActivitySeeds].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function decisionLocal(id){circleInit();let d=state.circleV11.decisions.find(d=>d.id===id);if(d)return d;d=state.circleV11.saved.find(d=>d.id===id);if(!d){const seed=circleDecisionSeeds.find(d=>d.id===id);if(!seed)return null;d={...seed,options:[...seed.options]};state.circleV11.saved.push(d)}return d}
function decisionOpen(d){return d.stage==='vote'&&d.deadline>=nowDate()}
function circleCover(kind){return kind==='house'?'assets/maison-l-bois-reference.webp':kind==='bike'?'assets/velos-photos.webp':'assets/jardin-photo.webp'}
function circleView(){circleInit();return `<section class="circle-hero"><img src="assets/jardin-photo.webp" alt="Visualisation du jardin et des espaces communs du Domaine"><div><div class="eyebrow">LE RÉSEAU SOCIAL DU PROJET</div><h1>Le Cercle du Domaine.</h1><p>Un lieu pour se connaître.<br>Des idées pour décider. Des moments à partager.</p><div class="circle-hero-actions"><button class="btn" onclick="circleComposer()">＋ Partager avec le Cercle</button><button class="btn light" onclick="circleRules()">Notre façon de vivre ensemble</button></div></div></section><div class="circle-context"><span class="avatar">AL</span><div><b>Alex · Habitat A03</b><small>Profil fictif de démonstration</small></div><p>Les publications, votes et inscriptions sont sauvegardés sur cet appareil. Les autres habitants ne les reçoivent pas encore.</p></div><div class="circle-tabs" aria-label="Espaces du réseau social">${[['fil','◎ Le fil du Domaine'],['decisions','◈ Décider ensemble'],['activites','▤ Activités & rencontres'],['entraide','↗ Entraide']].map(([id,label])=>`<button aria-pressed="${circleTab===id}" onclick="circleTab='${id}';render()">${label}</button>`).join('')}</div>${circleTab==='decisions'?circleDecisionView():circleTab==='activites'?circleActivityView():circleFeed(circleTab==='entraide')}`}
function circleFeed(help=false){const posts=allThreads().filter(t=>(!help||t.channel==='Entraide')&&(!circleQuery||(t.title+' '+t.text).toLowerCase().includes(circleQuery.toLowerCase())));return `<div class="circle-layout"><div><section class="panel circle-compose"><div><span class="avatar">AL</span><button onclick="circleComposer()">${help?'Un coup de main à demander ou à proposer ?':'Une idée, une nouvelle, un moment à partager ?'}</button></div><div class="circle-compose-links"><button onclick="circleComposer('Annonces')">Annoncer</button><button onclick="circleComposer('Entraide')">Proposer une aide</button><button onclick="circleTab='activites';render();circleActivityForm()">Créer une activité</button></div></section><form class="circle-search" onsubmit="event.preventDefault();circleQuery=this.query.value.trim();render()"><label for="circle-search">Rechercher dans le Cercle</label><div><input id="circle-search" name="query" value="${esc(circleQuery)}" type="search" placeholder="Sujet, idée, besoin…"><button class="btn light">Rechercher</button></div></form>${posts.map(t=>`<div class="circle-post">${(t.cover||t.id==='s1'||t.id==='s2')?`<img src="${circleCover(t.cover||(t.id==='s1'?'garden':'house'))}" alt="Visuel de présentation associé à cette publication" loading="lazy">`:''}${threadCard(t)}</div>`).join('')||'<section class="panel empty">Aucun échange pour cette recherche. Ouvrez une première discussion.</section>'}</div><aside class="circle-side"><section class="panel"><div class="eyebrow">LES SUJETS QUI NOUS RASSEMBLENT</div><h2 style="margin-top:16px">Un collectif qui avance.</h2><div class="circle-side-item"><b>◈ ${circleDecisions().filter(d=>decisionOpen(d)).length} vote(s) ouvert(s)</b><p>Des propositions et des résultats lisibles, sans scores cachés.</p><button class="textlink" onclick="circleTab='decisions';render()">Participer aux décisions ↗</button></div><div class="circle-side-item"><b>▤ ${circleActivities().filter(a=>a.date>=nowDate()).length} rendez-vous à découvrir</b><p>Au jardin, à table ou en balade.</p><button class="textlink" onclick="circleTab='activites';render()">Voir les activités ↗</button></div><div class="circle-side-item"><b>↗ L’entraide au quotidien</b><p>Prêter, demander un coup de main, proposer un savoir-faire.</p><button class="textlink" onclick="circleTab='entraide';render()">Rejoindre l’entraide ↗</button></div></section><section class="panel"><h3>Les outils du lieu</h3><a class="textlink" href="#velos">Réserver un vélo ↗</a><br><a class="textlink" href="#jardin">Suivre le potager ↗</a><br><a class="textlink" href="#ressources">Énergie, eau & Wi-Fi ↗</a></section></aside></div>`}
function circleComposer(channel='Annonces'){modal(`<div class="eyebrow">LE CERCLE · NOUVELLE PUBLICATION</div><h2 style="margin-top:16px">Partager avec le Domaine.</h2><form onsubmit="event.preventDefault();circlePublish(this)"><label for="circle-channel">Salon</label><select id="circle-channel" name="channel">${channels.slice(1).map(c=>`<option ${c===channel?'selected':''}>${c}</option>`).join('')}</select><label for="circle-title">Titre</label><input id="circle-title" name="title" maxlength="120" required placeholder="Le sujet de votre publication"><label for="circle-text">Message</label><textarea id="circle-text" name="text" maxlength="2000" required placeholder="Partagez une idée, un besoin ou une nouvelle…"></textarea><label for="circle-cover">Visuel de présentation</label><select id="circle-cover" name="cover"><option value="">Sans image</option><option value="garden">Le jardin commun</option><option value="house">La maison & la terrasse</option><option value="bike">Les vélos du Domaine</option></select><p class="smallnote">Publication de démo, visible dans ce navigateur uniquement. N’indiquez pas d’informations privées dans la présentation.</p><button class="btn" style="margin-top:15px">Publier dans le Cercle</button></form>`)}
function circlePublish(f){const title=f.title.value.trim(),text=f.text.value.trim();if(!title||!text){toast('Indiquez un titre et un message.');return}state.forum.threads.unshift({id:travelId('POST'),channel:f.channel.value,title,text,cover:f.cover.value,author:'Alex',initial:'AL',date:nowDate()});save();circleTab=f.channel.value==='Entraide'?'entraide':'fil';circleQuery='';$('#modal').close();render();toast('Publication ajoutée au Cercle de démonstration.')}
function circleDecisionView(){return `<div class="pagehead"><div><h2>Des propositions aux décisions.</h2><p class="sub">Discuter → ouvrir le vote → lire les résultats → organiser la suite.</p></div><button class="btn" onclick="circleDecisionForm()">＋ Proposer un sujet</button></div><div class="circle-principles"><span>Une idée claire</span><span>Un délai visible</span><span>Votre choix modifiable</span><span>Une trace de la décision</span></div><div class="decision-grid">${circleDecisions().map(circleDecisionCard).join('')}</div><p class="smallnote">Les votes représentent uniquement votre choix dans ce navigateur. Aucun vote collectif réel, quorum ou décision juridiquement contraignante n’est organisé ici.</p>`}
function circleDecisionCard(d){const open=decisionOpen(d),closed=d.stage==='closed'||d.deadline<nowDate(),total=Number.isInteger(d.choice)?1:0;return `<article class="panel decision-card"><div class="decision-top"><span class="booking-status">${closed?'Vote clôturé':d.stage==='discussion'?'En discussion':'Vote ouvert'}</span><span>${d.example?'Sujet fictif d’exemple':'Votre proposition locale'}</span></div><h3>${esc(d.title)}</h3><p>${esc(d.text)}</p><div class="decision-deadline">Échéance : ${displayDate(d.deadline)} · ${total} choix enregistré sur cet appareil</div><div class="decision-options">${d.options.map((o,i)=>`<button ${open?'':'disabled'} aria-pressed="${d.choice===i}" onclick="circleVote('${d.id}',${i})"><span>${d.choice===i?'●':'○'} ${esc(o)}</span><b>${d.choice===i?'1':'0'}</b><i style="width:${d.choice===i?100:0}%"></i></button>`).join('')}</div>${closed?`<div class="decision-result">${total?'Choix local enregistré : '+esc(d.options[d.choice]):'Aucun choix local enregistré.'}<small>Une synthèse de démonstration à discuter avec les habitants.</small></div>`:''}<div class="decision-actions"><button class="btn light" onclick="circleDecisionDiscussion('${d.id}')">Discuter du sujet</button>${!closed&&d.stage==='discussion'?`<button class="btn" onclick="circleDecisionStage('${d.id}','vote')">Ouvrir le vote fictif</button>`:open?`<button class="textlink" onclick="circleDecisionStage('${d.id}','closed')">Clore le vote de démo</button>`:''}</div></article>`}
function circleVote(id,i){const d=decisionLocal(id);if(!d||!decisionOpen(d)||!Number.isInteger(i)||i<0||i>=d.options.length)return;d.choice=i;save();render();toast('Votre choix local est enregistré. Vous pouvez le modifier avant la clôture.')}
function circleDecisionStage(id,stage){const d=decisionLocal(id);if(!d)return;if(stage==='vote'&&d.stage==='discussion'&&d.deadline>=nowDate())d.stage='vote';else if(stage==='closed'&&d.stage==='vote')d.stage='closed';else return;d.updated=nowDate();save();render();toast(stage==='vote'?'Vote fictif ouvert.':'Vote de démonstration clôturé. Synthèse conservée.')}
function circleDecisionDiscussion(id){const d=decisionLocal(id);if(!d)return;if(!d.thread){d.thread=travelId('SUJET');state.forum.threads.unshift({id:d.thread,channel:'Idées & décisions',title:d.title,text:d.text,author:'Alex',initial:'AL',date:nowDate()});save()}openThread(d.thread)}
function circleDecisionForm(){modal(`<div class="eyebrow">DÉCIDER ENSEMBLE</div><h2 style="margin-top:16px">Proposer un sujet.</h2><form onsubmit="event.preventDefault();circleCreateDecision(this)"><label for="decision-title">La question à traiter</label><input id="decision-title" name="title" required maxlength="120"><label for="decision-text">Contexte et objectif</label><textarea id="decision-text" name="text" required maxlength="1200"></textarea><label for="decision-options">Options · une par ligne (2 à 4)</label><textarea id="decision-options" name="options" required placeholder="Option 1&#10;Option 2"></textarea><label for="decision-deadline">Date limite</label><input type="date" id="decision-deadline" name="deadline" required min="${nowDate()}" value="${datePlus(nowDate(),7)}"><label for="decision-stage">Première étape</label><select id="decision-stage" name="stage"><option value="discussion">Ouvrir la discussion</option><option value="vote">Ouvrir un vote fictif</option></select><button class="btn" style="margin-top:20px">Créer la proposition locale</button></form>`)}
function circleCreateDecision(f){const options=[...new Set(f.options.value.split('\n').map(s=>s.trim()).filter(Boolean))];if(options.length<2||options.length>4||options.some(s=>s.length>100)){toast('Indiquez de 2 à 4 options différentes, de 100 caractères maximum.');return}if(!f.title.value.trim()||!f.text.value.trim()||!dateValid(f.deadline.value)||f.deadline.value<nowDate()){toast('Vérifiez le sujet, le contexte et la date limite.');return}state.circleV11.decisions.unshift({id:travelId('DEC'),title:f.title.value.trim(),text:f.text.value.trim(),options,deadline:f.deadline.value,stage:f.stage.value});save();$('#modal').close();render();toast('Proposition créée dans le Cercle local.')}
function circleActivityView(){return `<div class="pagehead"><div><h2>Des moments qui font collectif.</h2><p class="sub">Jardin, repas, ateliers ou balades : proposer, participer et se retrouver.</p></div><button class="btn" onclick="circleActivityForm()">＋ Créer une activité</button></div><div class="activity-grid">${circleActivities().map(a=>{const joined=state.circleV11.signups.includes(a.id),past=a.date<nowDate();return `<article class="stay-card activity-card"><img src="${circleCover(a.photo)}" alt="Visuel de présentation pour ${esc(a.title)}" loading="lazy"><div class="stay-body"><small>${esc(a.category)} · ${a.example?'activité fictive':'proposition locale'}</small><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p><div class="activity-info"><b>${displayDate(a.date)} · ${a.time}</b><span>${esc(a.place)}</span><span>${joined?'1 inscription sur cet appareil':'Aucune inscription sur cet appareil'} · ${a.capacity} places de scénario</span></div><button class="btn ${joined?'light':''}" ${past?'disabled':''} onclick="circleJoin('${a.id}')">${past?'Activité passée':joined?'Annuler mon inscription':'Je participe · démo'}</button>${a.category==='Mobilité'?'<a class="textlink" href="#velos">Réserver un vélo ↗</a>':''}</div></article>`}).join('')}</div>`}
function circleJoin(id){const a=circleActivities().find(a=>a.id===id);if(!a||a.date<nowDate())return;const list=state.circleV11.signups;state.circleV11.signups=list.includes(id)?list.filter(x=>x!==id):[...list,id];save();render();toast(state.circleV11.signups.includes(id)?'Inscription fictive enregistrée. Aucun organisateur contacté.':'Inscription de démonstration annulée.')}
function circleActivityForm(){modal(`<div class="eyebrow">FAIRE VIVRE LE DOMAINE</div><h2 style="margin-top:16px">Créer une activité.</h2><form onsubmit="event.preventDefault();circleCreateActivity(this)"><label for="activity-title">Nom de l’activité</label><input id="activity-title" name="title" required maxlength="100"><label for="activity-desc">Que proposez-vous ?</label><textarea id="activity-desc" name="desc" required maxlength="1000"></textarea><div class="formrow"><div><label for="activity-date">Date</label><input type="date" id="activity-date" name="date" required min="${nowDate()}" value="${datePlus(nowDate(),3)}"></div><div><label for="activity-time">Heure</label><input type="time" id="activity-time" name="time" required value="10:00"></div></div><label for="activity-place">Lieu</label><select id="activity-place" name="place"><option>Maison commune</option><option>Potager commun</option><option>Point mobilité</option><option>Place du marché</option></select><div class="formrow"><div><label for="activity-cat">Thème</label><select id="activity-cat" name="category"><option>Convivialité</option><option>Jardin</option><option>Mobilité</option><option>Atelier</option><option>Entraide</option></select></div><div><label for="activity-capacity">Places proposées</label><input type="number" id="activity-capacity" name="capacity" required min="1" max="50" value="8"></div></div><button class="btn" style="margin-top:20px">Publier l’activité fictive</button></form>`)}
function circleCreateActivity(f){const capacity=Number(f.capacity.value);if(!f.title.value.trim()||!f.desc.value.trim()||!dateValid(f.date.value)||f.date.value<nowDate()||!Number.isInteger(capacity)||capacity<1||capacity>50){toast('Vérifiez les informations de l’activité.');return}state.circleV11.activities.unshift({id:travelId('ACT'),title:f.title.value.trim(),desc:f.desc.value.trim(),date:f.date.value,time:f.time.value,place:f.place.value,category:f.category.value,capacity,photo:f.category.value==='Mobilité'?'bike':f.category.value==='Jardin'?'garden':'house'});save();$('#modal').close();render();toast('Activité créée. Les inscriptions restent dans la démo locale.')}
function circleRules(){modal(`<div class="eyebrow">LA VIE COMMUNE · NOTRE INTENTION</div><h2 style="margin-top:16px">Un collectif accueillant.</h2><div class="circle-rule"><b>1 · Chacun peut proposer</b><p>Décrire un besoin, une idée et les personnes concernées.</p></div><div class="circle-rule"><b>2 · Discuter avant de trancher</b><p>Écouter les avis, rendre les options visibles et annoncer la date limite.</p></div><div class="circle-rule"><b>3 · Garder une trace</b><p>Conserver les échanges, le résultat et les actions à organiser.</p></div><div class="circle-rule"><b>4 · Respecter les personnes</b><p>Préserver la confidentialité, partager avec respect et signaler un contenu inadapté.</p></div><p class="smallnote">Cette charte d’intention et les parcours de démonstration ne remplacent pas les règles à définir avec les habitants du projet réel.</p>`)}
views.communaute=circleView;routes.find(r=>r[0]==='communaute')[2]='Le Cercle · Vie commune';
const homeBeforeCircle=views.accueil;views.accueil=function(){let html=homeBeforeCircle();html=html.replace('Quelques jours ailleurs.<br>Une autre façon de vivre.','Un lieu à habiter.<br>Une vie à partager.');html=html.replace('<div class="sectiontitle"><div><div class="eyebrow">VOTRE PARENTHÈSE AU VERT</div>',`<section class="circle-home"><div><div class="eyebrow">LE CŒUR DU PROJET</div><h2>Une maison à soi.<br>Une vie à construire ensemble.</h2><p>Le Cercle relie les habitants : discuter des décisions, proposer une activité, organiser un repas ou donner un coup de main.</p><div class="circle-home-features"><span>◈ Décisions</span><span>▤ Activités</span><span>◎ Discussions</span><span>↗ Entraide</span></div><a class="btn" href="#communaute">Entrer dans le Cercle du Domaine ↗</a></div><img src="assets/jardin-photo.webp" alt="Visualisation du jardin partagé du Domaine" loading="lazy"></section><div class="sectiontitle"><div><div class="eyebrow">VOTRE PARENTHÈSE AU VERT</div>`);return html};
const mapActionBeforeCircle=cityAction;cityAction=function(id){if(id==='commun'){location.hash='#communaute';return}mapActionBeforeCircle(id)};
const resetBeforeCircle=resetDemo;resetDemo=function(){resetBeforeCircle();state.circleV11={decisions:[],activities:[],signups:[],saved:[]};circleInit();save();render()};
slides.splice(1,0,{k:'LA VIE COMMUNE',title:'Le cœur du Domaine,<br>c’est la vie ensemble.',text:'Des habitants qui se connaissent, des décisions discutées et des activités qui créent du lien. Le Cercle est le réseau social propre au projet.',cards:[['Décider ensemble','Proposer un sujet, discuter les options, ouvrir un vote et garder une trace.'],['Vivre des moments communs','Repas, récoltes, ateliers et balades avec inscriptions.'],['S’entraider','Un fil par sujet pour proposer, demander et partager.']]},{k:'LE CERCLE DU DOMAINE',title:'Une idée.<br>Une discussion. Une action.',text:'Le réseau relie les propositions à la vie concrète du lieu. Cette version permet de tester le parcours sur un appareil.',cards:[['Exprimer','Publier un besoin, une proposition ou une nouvelle du jardin.'],['Participer','Répondre à une discussion, exprimer un choix, s’inscrire.'],['Organiser','Retrouver les rendez-vous et les outils du Domaine.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^\d+ · /,''));
const slideBeforeCircle=renderSlide;renderSlide=function(){slideBeforeCircle();if(slides[slideIndex].k.includes('LA VIE COMMUNE')||slides[slideIndex].k.includes('LE CERCLE DU DOMAINE'))$('#slide .over').insertAdjacentHTML('beforeend','<a class="btn" href="#communaute" onclick="document.getElementById(\'deck\').close()">Découvrir le réseau du Domaine ↗</a>')};
// Accès direct sur téléphone et tablette, et dans la navigation du site.
const modernNavBeforeCircle=modernNavigation;modernNavigation=function(){modernNavBeforeCircle();const nav=$('#touch-nav');if(nav){const plan=nav.querySelector('a[href="#ville"]');if(plan){plan.href='#communaute';plan.innerHTML='<span>◎</span><b>Le Cercle</b>';plan.removeAttribute('aria-current');if(location.hash==='#communaute')plan.setAttribute('aria-current','page')}}};
const renderBeforeCircle=render;render=function(){renderBeforeCircle();const nav=$('#nav');if(!window.matchMedia('(max-width:850px)').matches){const group=nav.querySelector('.estate-nav-group');const link=nav.querySelector('a[href="#communaute"]');if(group&&link)nav.insertBefore(link,group)}const label=document.querySelector('.navlabel');if(label)label.textContent='HABITER · PARTAGER · EXPLORER'};
render();
